9	// scopedRenameReregisterFixture builds the rename-then-reregister regression
10	// lineage:
11	//
12	//	extra ──> detail                 (detail depends on an independent source)
13	//	source ──> detail ──> report     (the route through detail)
14	//	source ──> report                (the direct relation)
15	//	report ──> view                  (target downstream)
16	//
17	// source participates in report's derivation both directly and through
18	// detail, so a scoped source -> report export must keep both routes; extra,
19	// extra -> detail and view never take part and stay out.
20	func scopedRenameReregisterFixture(t *testing.T) map[string]*Lineage {
21		t.Helper()
22		return buildRegisteredGraph(t, [][]string{
23			{"source"},
24			{"extra"},
25			{"detail", "source", "extra"},
26			{"report", "source", "detail"},
27			{"view", "report"},
28		})
29	}
30	
31	// The exact scoped JSON texts. All orderings are fully determined by the
32	// names: nodes in Go string order, edges upstream -> derived ordered by from
33	// then to.
34	const (
35		// Before the rename: source -> report scoped export holds the direct edge
36		// and the route through detail, nothing else.
37		scopedRenameReregisterBefore = `{"nodes":["detail","report","source"],` +
38			`"edges":[{"from":"detail","to":"report"},{"from":"source","to":"detail"},` +
39			`{"from":"source","to":"report"}]}`
40		// After the rename, the renamed -> report export is the pre-rename
41		// document with the new name substituted: same three nodes, same three
42		// direct dependencies. The re-registration of the old name must not
43		// change this text either.
44		scopedRenameReregisterRenamed = `{"nodes":["detail","renamed","report"],` +
45			`"edges":[{"from":"detail","to":"report"},{"from":"renamed","to":"detail"},` +
46			`{"from":"renamed","to":"report"}]}`
47		// After the old name is registered again as a new source that report
48		// depends on directly: the source -> report export holds exactly the two
49		// endpoints and their new direct edge.
50		scopedRenameReregisterNewSource = `{"nodes":["report","source"],` +
51			`"edges":[{"from":"source","to":"report"}]}`
52		// The full upstream export of report after the re-registration sees both
