18		})
19		before := snapshotExportGraph(graph)
20	
21		out, err := ExportUpstreamLineage(graph, bad)
22		if err == nil {
23			t.Fatalf("export with invalid target succeeded with %q, want an encoding error", out)
24		}
25		if out != "" {
26			t.Errorf("failed export returned partial content %q, want empty string", out)
27		}
28		// The error must expose the actual byte (\xff) in Go-quoted form rather
29		// than a replacement glyph that cannot be told apart from any other bad
30		// byte.
31		if !strings.Contains(err.Error(), `"a\xffb"`) {
32			t.Errorf("error %q must quote the original bytes, want substring %q", err, `"a\xffb"`)
33		}
34		assertGraphUnchanged(t, before, graph)
